(7476530, 1188364, 76217, '<td valign="top">Reflective and timeless. Infused with spirit.</td>', 'Reflective and timeless. Infused with spirit.', '2016-10-02 00:50:05.000000', NULL, 1),
(7476531, 1188377, 76217, '<td valign="top">I can imagine wading in. Perhaps mucky. Perhaps buggy. And settling to rest.</td>', 'I can imagine wading in. Perhaps mucky. Perhaps buggy. And settling to rest.', '2016-10-02 00:52:11.000000', NULL, 1),
(7476532, 1187358, 76217, '<td valign="top">A bit manipulative. A bit ethereal. Extremely comforting.</td>', 'A bit manipulative. A bit ethereal. Extremely comforting.', '2016-10-02 00:57:26.000000', NULL, 1),
(7476533, 1188289, 76217, '<td valign="top">This is gritty and real. The perspective is great. I think the B&amp;W choice is wise.</td>', 'This is gritty and real. The perspective is great. I think the B&W choice is wise.', '2016-10-02 01:00:01.000000', NULL, 1),
(7476534, 1188406, 76217, '<td valign="top">Wow. This is very creepy and disturbing and makes me somewhat uncomfortable. Well done.</td>', 'Wow. This is very creepy and disturbing and makes me somewhat uncomfortable. Well done.', '2016-10-02 01:01:39.000000', NULL, 1),
(7476535, 1188400, 76217, '<td valign="top">Fabulous and a bizarre.DOF makes it more engaging.The table/bar and the green and copper background make the picture whole. An uncanny juxtaposition.</td>', 'Fabulous and a bizarre.DOF makes it more engaging.The table/bar and the green and copper background make the picture whole. An uncanny juxtaposition.', '2016-10-02 01:13:08.000000', NULL, 1),
(7476537, 1187883, 76217, '<td valign="top">Which one is Peter?</td>', 'Which one is Peter?', '2016-10-02 01:20:28.000000', NULL, 1),
(7476539, 1188446, 76217, '<td valign="top">I can color this in myself. The woman in the background gives the woman in the foreground wings. Perfectly cool.</td>', 'I can color this in myself. The woman in the background gives the woman in the foreground wings. Perfectly cool.', '2016-10-02 01:59:54.000000', NULL, 1),
(7476540, 1188318, 76217, '<td valign="top">I do like how you abstracted the subject. Teetering on surrealism.</td>', 'I do like how you abstracted the subject. Teetering on surrealism.', '2016-10-02 02:03:45.000000', NULL, 1),
(7476543, 1188439, 76217, '<td valign="top">I like this. I can''t tell you why precisely. The color, the texture, the ear, the nose, the dark mass? Exhumation?</td>', 'I like this. I can''t tell you why precisely. The color, the texture, the ear, the nose, the dark mass? Exhumation?', '2016-10-02 02:09:07.000000', NULL, 1),
