(7476574, 1188225, 98565, '<td valign="top">If you''d turn it 90 degrees to the right there would be a glowing angel...<br/>Outstanding nature show, perfectly captured! Will be back to vote</td>', 'If you''d turn it 90 degrees to the right there would be a glowing angel...Outstanding nature show, perfectly captured! Will be back to vote', '2016-10-02 12:40:19.000000', NULL, 1),
(7476576, 1188429, 98565, '<td valign="top">What a gorgeous nature!! For my taste there is too much going on in the foreground. The rocks - in fact everything - seem overdone with sharpening. Rocks and grass are distracting from the waterfall.</td>', 'What a gorgeous nature!! For my taste there is too much going on in the foreground. The rocks - in fact everything - seem overdone with sharpening. Rocks and grass are distracting from the waterfall.', '2016-10-02 12:45:37.000000', NULL, 1),
(7476668, 1188358, 76217, '<td valign="top">This is oddly sensual.Perhaps not oddly.</td>', 'This is oddly sensual.Perhaps not oddly.', '2016-10-02 20:58:07.000000', NULL, 1),
(7476674, 1188363, 40391, '<td valign="top">Perfect focus and lovely smooth bokeh.</td>', 'Perfect focus and lovely smooth bokeh.', '2016-10-02 21:20:03.000000', NULL, 1),
(7476675, 1188235, 40391, '<td valign="top">The prefect place to be. Silhouettes and orange works so well together here.</td>', 'The prefect place to be. Silhouettes and orange works so well together here.', '2016-10-02 21:22:40.000000', NULL, 1),
(7476676, 1188445, 40391, '<td valign="top">Peaceful.</td>', 'Peaceful.', '2016-10-02 21:24:17.000000', NULL, 1),
(7476677, 1187946, 40391, '<td valign="top">This works very nicely for me. Even though the focus is strikingly strict to the nose, the eyes still tells the story giving the whole image meaning. And it''s a fun shot.</td>', 'This works very nicely for me. Even though the focus is strikingly strict to the nose, the eyes still tells the story giving the whole image meaning. And it''s a fun shot.', '2016-10-02 21:28:04.000000', NULL, 1),
(7476678, 1188407, 40391, '<td valign="top">I like the strong contrasts and vivid whites. The sole figure in the roof adds a nice bit of interest too.</td>', 'I like the strong contrasts and vivid whites. The sole figure in the roof adds a nice bit of interest too.', '2016-10-02 21:30:18.000000', NULL, 1),
(7476679, 1188289, 40391, '<td valign="top">He is so interesting. I like the location also.</td>', 'He is so interesting. I like the location also.', '2016-10-02 21:32:23.000000', NULL, 1),
(7476680, 1188414, 40391, '<td valign="top">Beautiful layers. Motion blur done well</td>', 'Beautiful layers. Motion blur done well', '2016-10-02 21:33:25.000000', NULL, 1),
(7476681, 1188447, 40391, '<td valign="top">I like the pose and balance with the silhouetted leaf at the left.</td>', 'I like the pose and balance with the silhouetted leaf at the left.', '2016-10-02 21:34:58.000000', NULL, 1),
(7476682, 1188126, 40391, '<td valign="top">Wonderful angles that lack sense makes for a wonderful abstract image.</td>', 'Wonderful angles that lack sense makes for a wonderful abstract image.', '2016-10-02 21:37:35.000000', NULL, 1),
(7476683, 1188410, 40391, '<td valign="top">He really seams yo be enjoying himself. Nicely timed capture.</td>', 'He really seams yo be enjoying himself. Nicely timed capture.', '2016-10-02 21:39:10.000000', NULL, 1),
(7476684, 1188432, 40391, '<td valign="top">I feel the serenity.</td>', 'I feel the serenity.', '2016-10-02 21:39:44.000000', NULL, 1),
(7476685, 1188429, 40391, '<td valign="top">Nice capture of the moving water.</td>', 'Nice capture of the moving water.', '2016-10-02 21:40:44.000000', NULL, 1),
(7476686, 1188417, 40391, '<td valign="top">Amazing capture! I would like to see this as a pure black &amp; white though I don''t mind the blue. Up there with the best storm shots I''ve seen.</td>', 'Amazing capture! I would like to see this as a pure black & white though I don''t mind the blue. Up there with the best storm shots I''ve seen.', '2016-10-02 21:44:17.000000', NULL, 1),
(7476687, 1188431, 40391, '<td valign="top">The people in the reflection makes this image for me.</td>', 'The people in the reflection makes this image for me.', '2016-10-02 21:47:46.000000', NULL, 1),
(7476688, 1188389, 40391, '<td valign="top">To me it is more like the methane surface of Venus. Either way definitely an alien landscape. Lovely.</td>', 'To me it is more like the methane surface of Venus. Either way definitely an alien landscape. Lovely.', '2016-10-02 21:49:49.000000', NULL, 1),
(7476693, 1188420, 40391, '<td valign="top">Nice perspective. I''m sure the one on the left is smiling at whatever the other one is saying.</td>', 'Nice perspective. I''m sure the one on the left is smiling at whatever the other one is saying.', '2016-10-02 21:55:24.000000', NULL, 1),
(7476694, 1188433, 40391, '<td valign="top">Wonderful capture. You''ve brought out the shadows well too.</td>', 'Wonderful capture. You''ve brought out the shadows well too.', '2016-10-02 21:56:31.000000', NULL, 1),
(7476696, 1188406, 40391, '<td valign="top">My initial thought was ''romantic''. But with a bit more of a look there is something more sinister in this shot. Quite probably just the timing. It does make for an interesting story.</td>', 'My initial thought was ''romantic''. But with a bit more of a look there is something more sinister in this shot. Quite probably just the timing. It does make for an interesting story.', '2016-10-02 22:00:33.000000', NULL, 1),
(7476697, 1188261, 40391, '<td valign="top">A strange combination that makes perfect sense.</td>', 'A strange combination that makes perfect sense.', '2016-10-02 22:01:18.000000', NULL, 1),
(7476699, 1187656, 40391, '<td valign="top">Beautiful contrasts.</td>', 'Beautiful contrasts.', '2016-10-02 22:02:28.000000', NULL, 1),
(7476700, 1188443, 40391, '<td valign="top">I really like this kind of shot and can appreciate the difficulty in getting it. Great capture!</td>', 'I really like this kind of shot and can appreciate the difficulty in getting it. Great capture!', '2016-10-02 22:04:38.000000', NULL, 1),
(7476702, 1188162, 40391, '<td valign="top">Vivid! Beautiful too.</td>', 'Vivid! Beautiful too.', '2016-10-02 22:05:58.000000', NULL, 1),
(7476703, 1188394, 40391, '<td valign="top">A beautiful model and nice bokeh. A slightly deeper depth-of-field to get both eyes in focus would have been good.</td>', 'A beautiful model and nice bokeh. A slightly deeper depth-of-field to get both eyes in focus would have been good.', '2016-10-02 22:09:08.000000', NULL, 1),
(7476706, 1188405, 40391, '<td valign="top">I like the symmetry. A fantastic capture of the aurora borealis.</td>', 'I like the symmetry. A fantastic capture of the aurora borealis.', '2016-10-02 22:13:44.000000', NULL, 1),
(7476707, 1188446, 40391, '<td valign="top">A very professional looking result.</td>', 'A very professional looking result.', '2016-10-02 22:14:31.000000', NULL, 1),
(7476708, 1188200, 40391, '<td valign="top">It feels very lonely there.</td>', 'It feels very lonely there.', '2016-10-02 22:15:28.000000', NULL, 1),
(7476709, 1187388, 40391, '<td valign="top">Nice eye contact.</td>', 'Nice eye contact.', '2016-10-02 22:16:01.000000', NULL, 1),
