(7476736, 1188307, 40391, '<td valign="top">He stands out quite nicely.</td>', 'He stands out quite nicely.', '2016-10-02 22:42:39.000000', NULL, 1),
(7476741, 1187883, 40391, '<td valign="top">Fantastic image! You''ve isolated them nicely too.</td>', 'Fantastic image! You''ve isolated them nicely too.', '2016-10-02 22:50:36.000000', NULL, 1),
