(7476784, 1188437, 40391, '<td valign="top">Quite the standout. Nice find.</td>', 'Quite the standout. Nice find.', '2016-10-03 01:31:15.000000', NULL, 1),
(7476787, 1188329, 40391, '<td valign="top">That is some headpiece.</td>', 'That is some headpiece.', '2016-10-03 01:32:42.000000', NULL, 1),
(7476788, 1187685, 40391, '<td valign="top">Great find. Wonderful colours.</td>', 'Great find. Wonderful colours.', '2016-10-03 01:33:56.000000', NULL, 1),
(7476790, 1188336, 40391, '<td valign="top">Great layers and wonderful light.</td>', 'Great layers and wonderful light.', '2016-10-03 01:34:36.000000', NULL, 1),
(7476792, 1187502, 40391, '<td valign="top">Those eyes are pleading "PLAY". Nice conversion to black &amp; white.</td>', 'Those eyes are pleading "PLAY". Nice conversion to black & white.', '2016-10-03 01:36:22.000000', NULL, 1),
(7476794, 1188416, 40391, '<td valign="top">Pretty cool lighting. Nice catch.</td>', 'Pretty cool lighting. Nice catch.', '2016-10-03 01:47:07.000000', NULL, 1),
(7476795, 1188441, 40391, '<td valign="top">I think she was my Head Mistress at primary school.</td>', 'I think she was my Head Mistress at primary school.', '2016-10-03 01:48:14.000000', NULL, 1),
(7476796, 1187988, 40391, '<td valign="top">Unhappy is universal.</td>', 'Unhappy is universal.', '2016-10-03 01:48:58.000000', NULL, 1),
(7476797, 1188285, 40391, '<td valign="top">Mystical. Beautiful light.</td>', 'Mystical. Beautiful light.', '2016-10-03 01:50:03.000000', NULL, 1),
(7476798, 1188430, 40391, '<td valign="top">Nice shallow depth of field. However, the focus needed to be on her eyes. Especially when you''ve captured that eye contact so well.</td>', 'Nice shallow depth of field. However, the focus needed to be on her eyes. Especially when you''ve captured that eye contact so well.', '2016-10-03 01:52:20.000000', NULL, 1),
(7476810, 1187269, 40391, '<td valign="top">Nice social commentary. The way I see thing here is that he is disconnected with his surroundings, so he is alone. Whilst the older couple behind are engaged with the world and each other so they have companionship. The truth is more likely he is listening to some wonderful music whilst texting his friends to see where they can get together. Oh, and the older couple are just lost and confused as they can''t remember where they parked their car. <br/> <br/>A photo can tell a multitude of stories.</td>', 'Nice social commentary. The way I see thing here is that he is disconnected with his surroundings, so he is alone. Whilst the older couple behind are engaged with the world and each other so they have companionship. The truth is more likely he is listening to some wonderful music whilst texting his friends to see where they can get together. Oh, and the older couple are just lost and confused as they can''t remember where they parked their car.  A photo can tell a multitude of stories.', '2016-10-03 01:59:00.000000', NULL, 1),
(7476816, 1188288, 40391, '<td valign="top">You''ve captured a wonderful look and smile. He is extremely cute.</td>', 'You''ve captured a wonderful look and smile. He is extremely cute.', '2016-10-03 02:01:14.000000', NULL, 1),
(7476820, 1188079, 40391, '<td valign="top">Great action shot and well done on getting the whole picture and story. This could grace the back page of any news paper.</td>', 'Great action shot and well done on getting the whole picture and story. This could grace the back page of any news paper.', '2016-10-03 02:02:30.000000', NULL, 1),
(7476822, 1188442, 40391, '<td valign="top">Quite an exciting image. I feel there needs to be a definitive spot to be in focus to allow my eyes to rest. It is a great capture though.</td>', 'Quite an exciting image. I feel there needs to be a definitive spot to be in focus to allow my eyes to rest. It is a great capture though.', '2016-10-03 02:04:35.000000', NULL, 1),
(7476823, 1188037, 40391, '<td valign="top">Nicely framed and pretty colours. The bird makes the shot though.</td>', 'Nicely framed and pretty colours. The bird makes the shot though.', '2016-10-03 02:05:38.000000', NULL, 1),
(7476824, 1188300, 40391, '<td valign="top">Quite interesting and I rather like the two dimensional feel too.</td>', 'Quite interesting and I rather like the two dimensional feel too.', '2016-10-03 02:14:24.000000', NULL, 1),
(7476825, 1188035, 40391, '<td valign="top">Beautiful image and wonderful symmetry.</td>', 'Beautiful image and wonderful symmetry.', '2016-10-03 02:15:26.000000', NULL, 1),
(7476826, 1187789, 40391, '<td valign="top">Do many layers. Lovely tones too.</td>', 'Do many layers. Lovely tones too.', '2016-10-03 02:17:34.000000', NULL, 1),
(7476827, 1188279, 40391, '<td valign="top">Just like candy. Lovely sky too.</td>', 'Just like candy. Lovely sky too.', '2016-10-03 02:18:30.000000', NULL, 1),
